export function formatBytes(input: number[]): string {
  let output = ""
  const slot0 = (input[0] || 0).toString(16).padStart(2, "0")
  const slot1 = (input[1] || 0).toString(16).padStart(2, "0")
  const slot2 = (input[2] || 0).toString(16).padStart(2, "0")
  const slot3 = (input[3] || 0).toString(16).padStart(2, "0")
  const slot4 = (input[4] || 0).toString(16).padStart(2, "0")
  const slot5 = (input[5] || 0).toString(16).padStart(2, "0")
  const slot6 = (input[6] || 0).toString(16).padStart(2, "0")
  const slot7 = (input[7] || 0).toString(16).padStart(2, "0")
  const slot8 = (input[8] || 0).toString(16).padStart(2, "0")
  const slot9 = (input[9] || 0).toString(16).padStart(2, "0")
  const slot10 = (input[10] || 0).toString(16).padStart(2, "0")
  const slot11 = (input[11] || 0).toString(16).padStart(2, "0")
  output = slot0 + slot1 + slot2 + slot3 + slot4 + slot5 + slot6 + slot7 + slot8 + slot9 + slot10 + slot11
  return output.toUpperCase()
 }

